"""Reconcile the complete historical Phase 3 research brief against bounded successor evidence."""
from pathlib import Path
from fractions import Fraction as F
import json, hashlib, collections

P = Path('docs/planning')
B = P / 'campaign3-history-universe-rev1'
O = P / 'campaign3-history-phase3-brief-rev1'
source = next(Path('reference').glob('*Phase 3 Research Brief*')).as_posix()

def load(p): return json.loads(Path(p).read_text(encoding='utf-8-sig'))
def ref(p): return dict(path=Path(p).as_posix(), sha256=hashlib.sha256(Path(p).read_bytes()).hexdigest())
def save(p, v):
    if p.exists(): assert load(p) == v, p
    else: p.write_text(json.dumps(v, ensure_ascii=False, indent=2)+'\n', encoding='utf-8', newline='\n')

groups = [(1, 301, 'SUPERSEDED RESEARCH PROPOSAL', 'Paused additive 3A/3B/3C hypothesis source, not current architectural authority or executed gate. Exact arithmetic, explicit RNG addresses and truth/perception/belief/appraisal separation survive. Seven-dimensional P and proposed state extension are candidates, not the full current topology.'), (302, 419, 'PREDICTION KEYS / ROLE SEMANTICS', 'Typed conditional outcomes differ from emotional labels. Original affected referent alone is insufficient for the later distinct appraisal anchor; implementation plan corrects this. Canonical predicate ordering must preserve argument roles: sorting directed predicate arguments is not justified by canonicalization prose.'), (420, 678, 'BELIEF / OPPORTUNITY / PROVENANCE', 'Mean and evidence weight are a candidate, not a full posterior or calibrated correctness probability. Positive confidence scale and update denominators need domains. Likelihood differs from conditional severity; safe opportunity teaches likelihood only. Outcome, observable safe exposure, censored and no opportunity remain distinct; absence per tick is not evidence. Coverage provenance is not proof of arbitrary correlation handling.'), (679, 913, 'FACTOR APPRAISAL / AGENCY', 'Likelihood, severity, vulnerability, control and immediacy are separately manipulable operands. Candidate p*s*(1+V)/2*(2-C)/2 can collapse equal p*s pairs despite distinct factors; A9 does not prove scalar output distinguishes all such cases. Confidence weighting, unknown control and max over available learned mitigation need explicit semantics. Threat motives do not command behavior. Later AFFECT preserves factors but leaves scalar equivalence/general laws unresolved.'), (914, 1026, 'RELIEF VERSUS EVIDENCE', 'Threat-load decrease and learned relief differ from factual probability updates and Need satisfaction. Leaving a dangerous context can reinforce escape while censoring correction; no automatic negative outcome evidence or fake Need is earned. Proposed example is not execution receipt.'), (1027, 1173, 'EXTINCTION / GENERALIZATION / FALSE BELIEF', 'Observable safe exposure differs from absence without opportunity. Generalization must affect the new target belief/appraisal, not merely cue accessibility. Directed attenuation and concept structure are candidate mechanisms, not necessary primitives. Cue retrieval, current presence and falsely believed danger remain distinct.'), (1174, 1310, 'UNEXECUTED FEAR SUITE', 'A1..A14, anxiety probe and fifteen gates are requirements, not passed experiments. Equal-product factor pairs need interpretation as distinct factor records unless scalar discrimination is actually demonstrated. Bravery requires choice/evidence rather than fear state alone; anxiety probe does not qualify all anxiety phenomena.'), (1311, 1563, 'OBSERVER SOCIAL BELIEF', 'No target private-state access. Earlier inferable-intent wording is restricted by later implementation plan: communication is an admitted claim, not verified private intent. Shared prediction machinery, derived trust/suspicion and embarrassment timing are hypotheses, not proof no additional state is needed. Labels and target identity truth are not observer belief.'), (1564, 1717, 'SOCIAL CORRELATION / PROPOSED SUITE', 'Deduplicate correlated reports within appropriate prediction target; one event may legitimately support different propositions. Jealousy probe, B1..B12 and social gates remain proposed evidence burdens. Later SOCIAL/RELATIONSHIP/identity-belief/embarrassment qualifications have their own finite scopes, not retroactive complete execution of this suite.'), (1718, 2008, 'CONSTITUTION / LEARNING CANDIDATES', 'Fixed P, quadratic projections and extra primitive competitors remain research candidates. Appraisal modulation differs from evidence learning bias and standing modifier; no fabricated observations. Seven dimensions do not exclude current developmental plasticity or settle ThreatSensitivity/UncertaintyTolerance irreducibility. Appraisal-only versus learning-rate effects requires actual matched evidence comparisons.'), (2009, 2235, 'CONSTITUTION VERSUS BIOGRAPHY', 'Separate constitutional and acquired standing contributors; neither directly creates identity evidence. Same evidence/different P, same P/different biography and conflict experiments are proposed matched interventions. Different standing alone cannot prove changed appraisal. Strong tendencies need not command contested choice. C1..C12 and fixed-seven-dimensional gate are superseded proposal scope, not current completion definition.'), (2236, 2348, 'PIPELINE / ORDER / DECAY', 'Every causal arrow needs actual owner/timing/trace proof; diagram alone is not native integration. Canonical same-time aggregation or explicit order, serialization and decay clock must be specified. Memory decay does not license untested belief precision decay. EffectProvenance in a pipeline must not bypass current observer read boundaries.'), (2349, 2495, 'MEMORY / ACCESS / BELIEF / IDENTITY', 'Retrieval accessibility, belief, Need expectation, prediction, acquired identity and represented self-belief remain distinct. Statement EvidenceBasis prevents repeated independent evidence is an obligation, not proof supplied by the type name. Explicit retrieval learning/deduplication law required; later defining-memory rehearsal is not automatic repeated independent world observation. Multiple motives from one event still need proper correlation/role partition. Feeling fear is not identity authorship.'), (2496, 2729, 'REGRESSION / ILLUSTRATIVE TRACES', 'Semantic labels are pattern targets, not bespoke flags. SURVIVES/REFINED/RETRACTED regression discipline survives. Threat, fear-learning, social and constitutional trace blocks are illustrative requirements with ellipses, not executed logs or numeric results. No new runtime tests inferred from this review.'), (2730, 2919, 'CLASSIFICATION / DEFERRED SCOPE', 'Ten classifications and ten research questions are open proposal targets, not demonstrated reductions. No-new-stat initial baselines are not universal bans on later earned state. Self-belief, plasticity, biology and relationship successors have separate accepted scope. Production semantic obligations do not choose Vivarium storage or prove general model sufficiency.'), (2920, 3023, 'FINAL GATE / CURRENT AUTHORITY', 'Twenty-six historical final-gate requirements and core principles are preserved, but paused additive program and seven-dimensional ontology do not replace Campaign 3 formal/corpus gates. Exact deterministic compilation and evidence-relative belief remain constraints; list of possible actions is not proof all behavior types have executed. All conclusions still require actual pipeline evidence and current source/freshness adequacy.')]
entries={e['path']:e for e in load(B/'manifest.json')['entries']}
assert ref(source)['sha256']==entries[source]['sha256']
assert len(Path(source).read_text(encoding='utf-8').splitlines())==3023
chainpaths=['CHARACTER_ARCHITECTURE.md','CharacterLab — Ideal Character Research Program Brief.md',str(P/'REFERENCE_MECHANISM_LEDGER.md'),str(P/'CAMPAIGN3_HISTORY_MECHANISMS_CHECKPOINT.md'),str(P/'CAMPAIGN3_HISTORY_VALUES_ADDITION_CHECKPOINT.md'),str(P/'CAMPAIGN3_BELIEF_QUALIFICATION.md'),str(P/'CAMPAIGN3_HISTORY_REFERENCE_README_CHECKPOINT.md'),str(P/'CAMPAIGN3_HISTORY_BIOLOGY_SOURCES_CHECKPOINT.md'),str(P/'CAMPAIGN3_HISTORY_DEFINING_PUBLIC_CHECKPOINT.md'), 'reference/RESEARCH.md', 'reference/src/model/semanticExperience.ts', str(P/'CAMPAIGN3_AFFECT_QUALIFICATION.md'), str(P/'CAMPAIGN3_DEFINING_PUBLIC_QUALIFICATION.md'), str(P/'CAMPAIGN3_HISTORY_PHASE3_PLAN_CHECKPOINT.md'), str(P/'campaign3-history-research-identity-rev1/review.json'), str(P/'CAMPAIGN3_HISTORY_REASON_AUTHORITY_CHECKPOINT.md'), str(P/'campaign3-history-reference-readme-rev2/tests.json')]
chain=[ref(p) for p in chainpaths]
rows=[]
with (B/'units.jsonl').open(encoding='utf-8') as f:
    for line in f:
        u=json.loads(line)
        if u['source']!=source: continue
        a,b=u['location']['startLine'],u['location']['endLine']
        selected=[g for g in groups if g[0]<=a<=b<=g[1]]
        assert len(selected)==1,(a,b)
        g=selected[0]
        rows.append(dict(occurrenceId=u['id'],source=source,sourceSha256=u['sourceSha256'],location=u['location'],text=u['text'],role=g[2],judgment=g[3]))
assert len(rows)==len({r['occurrenceId'] for r in rows})
O.mkdir(exist_ok=True)

obs=['RO-C3-001','RO-C3-009','RO-C3-010','RO-C3-011','RO-C3-019','RO-C3-020','RO-C3-021']
role=dict(**ref(source),role='SUPERSEDED PHASE3 RESEARCH BRIEF',judgment='All 3023 lines read and reconciled. Proposed tests and illustrative traces remain requirements, not results. Preserve distinct appraisal factors, opportunity evidence, observer-relative social belief, constitutional versus acquired contributors, and repeated-evidence safeguards. No universal scalar reduction, confidence calibration or seven-dimensional necessity earned.',acceptanceChain=chain)
review=dict(status='WHOLE PHASE3 RESEARCH BRIEF RECONCILED; HQ011 OPEN',sourceRoles=[role],reviewedLineRanges=[[1,3023]],rows=rows,scopeFindings=[dict(startLine=a,endLine=b,role=r,judgment=j) for a,b,r,j in groups],obligations=obs,limits=['No new runtime test or full historical suite rerun.','Equal-product threat limitation is algebraic scope analysis, not behavioral experiment.','Formula pin, legacy log, GA provenance and remaining source/freshness adequacy remain open.'])
save(O/'review.json',review)
save(O/'check.json',dict(status='PASS; HQ011 OPEN',sources=1,originalNarrativeOccurrences=len(rows),originalBackingOccurrences=0,sectionGroups=len(groups),checker=ref(__file__)))
v=load(P/'campaign3-history-source-roles-rev68/index.json');roles={r['path']:r for r in v['roleAssignments']}
assert source not in roles
roles[source]=dict(path=source,sha256=role['sha256'],category='WHOLE_PHASE3_BRIEF_REVIEWED',role=role['role'],scope=role['judgment'],evidence=[ref(O/'review.json')],acceptanceChain=role['acceptanceChain'])
v['version']='campaign3-history-source-roles/0.69';v['predecessor']=ref(P/'campaign3-history-source-roles-rev68/index.json')
v['roleAssignments']=[roles[p] for p in sorted(roles)];v['unassignedCandidatePaths']=sorted(set(entries)-set(roles));v['reviewedInputs'].append(ref(O/'review.json'))
v['originalNarrativeOrFindingOccurrences']+=len(rows);v['backingBreakdown']['phase3Brief']=0
v['rules'].append('REV69 adds whole historical Phase3 research brief. Proposed gates/traces are not execution receipts. Preserve factor/scalar distinction, valid opportunities, observer boundaries, constitution/biography separation and explicit repeated-evidence rules. Seven-dimensional P and initial no-extra-state proposals do not override current authority.')
I=P/'campaign3-history-source-roles-rev69';I.mkdir(exist_ok=True);save(I/'index.json',v)
check=dict(status=v['status'],candidateFiles=len(entries),assignedSources=len(roles),unassignedWithinThisIndex=len(v['unassignedCandidatePaths']),originalNarrativeOrFindingOccurrences=v['originalNarrativeOrFindingOccurrences'],originalBackingOccurrences=v['originalBackingFieldOccurrences'],explicitArchivesOutsideCensus=len(v['explicitBackingOutsideProseManifest']),indexSha256=ref(I/'index.json')['sha256'],checkerSha256=ref(__file__)['sha256'])
save(I/'check.json',check);print(json.dumps(check))
